      createdLibrariesIds.push(commonLibraryName);
      await sitesApi.createSite(commonTrashLibraryName);
      await sitesApi.deleteSites([commonTrashLibraryName], false);
    } catch (error) {
      console.error(`beforeAll failed : ${error}`);
