      await myLibrariesPage.selectCreateLibrary();
    } catch (error) {
      console.error(`beforeEach failed : ${error}`);
    }
  });

  test.afterAll(async () => {
    try {
      await sitesApi.deleteSites(createdLibrariesIds);
      const trashcanApi = await TrashcanApi.initialize(username, username);
